-- Schema for Screen Time Wallet Clone (Postgres / Supabase with RLS)
-- Generated by /replica-architect from replica/recon.md

create extension if not exists "pgcrypto";

-- Helper trigger function to keep updated_at current in UTC
create or replace function set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- =============================================================================
-- 1. wallet_profiles
-- Stores user wallet state, credit balance (in integer hundredths to prevent
-- float drift, where 1500 = 15.00 credits), card customization, and settings.
-- =============================================================================
create table wallet_profiles (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null unique, -- references auth.users(id) on delete cascade
  username text not null unique
    constraint username_format check (char_length(username) between 3 and 24),
  display_name text not null default 'Card Holder',
  credit_balance_hundredths integer not null default 1500
    constraint non_negative_balance check (credit_balance_hundredths >= 0),
  exchange_rate_hundredths_per_min integer not null default 100
    constraint positive_exchange_rate check (exchange_rate_hundredths_per_min between 10 and 10000),
  card_skin_id text not null default 'metal-classic'
    constraint valid_card_skin check (
      card_skin_id in (
        'metal-classic', 'metal-obsidian',
        'circuit-dark', 'circuit-silver', 'circuit-stripe',
        'weave-carbon', 'weave-cobalt', 'weave-crimson',
        'urban-gold', 'urban-sticker', 'urban-graffiti'
      )
    ),
  card_label text not null default 'LOCK IN CARD'
    constraint card_label_length check (char_length(card_label) <= 20),
  uninstall_protection_enabled boolean not null default false,
  biometric_withdraw_enabled boolean not null default false,
  motion_detection_enabled boolean not null default true,
  motion_sensitivity text not null default 'medium'
    constraint valid_motion_sensitivity check (motion_sensitivity in ('low', 'medium', 'high')),
  is_premium boolean not null default false,
  premium_plan_price_cents integer not null default 0
    constraint non_negative_price check (premium_plan_price_cents >= 0),
  premium_plan_currency text not null default 'USD'
    constraint currency_iso_len check (char_length(premium_plan_currency) = 3),
  user_timezone text not null default 'UTC',
  onboarding_completed boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index idx_wallet_profiles_user_id on wallet_profiles (user_id);
create index idx_wallet_profiles_username on wallet_profiles (username);

create trigger trg_wallet_profiles_updated_at
before update on wallet_profiles
for each row execute function set_updated_at();

-- =============================================================================
-- 2. block_rules
-- Stores persistent default-locked apps, categories, and website domains.
-- =============================================================================
create table block_rules (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references wallet_profiles(user_id) on delete cascade,
  target_type text not null
    constraint valid_target_type check (target_type in ('app', 'category', 'domain')),
  package_or_domain text not null,
  display_name text not null,
  category text not null default 'social'
    constraint valid_block_category check (
      category in ('social', 'games', 'video', 'messaging', 'browsers', 'shopping', 'other')
    ),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint unique_user_target unique (user_id, target_type, package_or_domain)
);

create index idx_block_rules_user_active on block_rules (user_id, is_active);

create trigger trg_block_rules_updated_at
before update on block_rules
for each row execute function set_updated_at();

-- =============================================================================
-- 3. focus_sessions
-- Tracks timed focus sessions (standard, screen-off, motion-strict, AR vault).
-- Hard constraint: a user can have at most ONE 'active' focus session at a time.
-- =============================================================================
create table focus_sessions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references wallet_profiles(user_id) on delete cascade,
  mode text not null default 'standard'
    constraint valid_focus_mode check (mode in ('standard', 'screen_off', 'motion_strict', 'ar_vault')),
  planned_duration_sec integer not null
    constraint positive_planned_duration check (planned_duration_sec between 60 and 28800),
  actual_duration_sec integer not null default 0
    constraint non_negative_actual_duration check (actual_duration_sec >= 0),
  status text not null default 'active'
    constraint valid_focus_status check (
      status in ('active', 'completed', 'forfeited_motion', 'forfeited_clock_tamper', 'cancelled')
    ),
  credits_earned_hundredths integer not null default 0
    constraint non_negative_credits_earned check (credits_earned_hundredths >= 0),
  motion_warnings_count integer not null default 0
    constraint non_negative_warnings check (motion_warnings_count >= 0),
  started_at timestamptz not null default now(),
  ended_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint valid_focus_end_time check (ended_at is null or ended_at >= started_at)
);

-- Race-condition prevention: only one active focus session per user at a time
create unique index idx_focus_sessions_one_active_per_user
  on focus_sessions (user_id)
  where status = 'active';

create index idx_focus_sessions_user_started on focus_sessions (user_id, started_at desc);

create trigger trg_focus_sessions_updated_at
before update on focus_sessions
for each row execute function set_updated_at();

-- =============================================================================
-- 4. unlock_sessions
-- Tracks screen-time withdrawals (starting at 1 minute) and early re-lock refunds.
-- Hard constraint: only ONE 'active' unlock session per user at a time.
-- =============================================================================
create table unlock_sessions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references wallet_profiles(user_id) on delete cascade,
  requested_minutes integer not null
    constraint min_one_minute_withdrawal check (requested_minutes between 1 and 480),
  exchange_rate_hundredths_per_min integer not null
    constraint valid_session_rate check (exchange_rate_hundredths_per_min > 0),
  credits_spent_hundredths integer not null
    constraint positive_credits_spent check (credits_spent_hundredths > 0),
  credits_refunded_hundredths integer not null default 0
    constraint valid_refund_amount check (
      credits_refunded_hundredths >= 0
      and credits_refunded_hundredths <= credits_spent_hundredths
    ),
  biometric_verified boolean not null default false,
  status text not null default 'active'
    constraint valid_unlock_status check (status in ('active', 'expired', 'relocked_early')),
  started_at timestamptz not null default now(),
  expires_at timestamptz not null,
  relocked_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint valid_unlock_window check (expires_at > started_at)
);

-- Race-condition prevention: only one active unlock session per user at a time
create unique index idx_unlock_sessions_one_active_per_user
  on unlock_sessions (user_id)
  where status = 'active';

create index idx_unlock_sessions_user_started on unlock_sessions (user_id, started_at desc);
create index idx_unlock_sessions_active_expiry on unlock_sessions (expires_at) where status = 'active';

create trigger trg_unlock_sessions_updated_at
before update on unlock_sessions
for each row execute function set_updated_at();

-- =============================================================================
-- 5. ledger_transactions
-- Immutable bank-statement ledger of every credit change.
-- Idempotency key guarantees retries never double-credit or double-debit.
-- =============================================================================
create table ledger_transactions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references wallet_profiles(user_id) on delete cascade,
  type text not null
    constraint valid_ledger_type check (
      type in ('starting_bonus', 'focus_earn', 'withdraw_spend', 'relock_refund', 'motion_penalty')
    ),
  amount_hundredths integer not null
    constraint non_zero_ledger_amount check (amount_hundredths <> 0),
  balance_after_hundredths integer not null
    constraint non_negative_balance_after check (balance_after_hundredths >= 0),
  reference_id uuid,
  idempotency_key text not null unique,
  description text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index idx_ledger_transactions_user_created on ledger_transactions (user_id, created_at desc);
create index idx_ledger_transactions_user_type on ledger_transactions (user_id, type);

create trigger trg_ledger_transactions_updated_at
before update on ledger_transactions
for each row execute function set_updated_at();

-- =============================================================================
-- 6. ad_impressions
-- Tracks the 3 free-tier ad placements:
--   1. focus_top_pill      (S06 top banner during active focus session)
--   2. post_session_card   (S08 card after focus session ends)
--   3. dashboard_native    (S04 compact native ad on Wallet Home)
-- =============================================================================
create table ad_impressions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references wallet_profiles(user_id) on delete cascade,
  placement text not null
    constraint valid_ad_placement check (
      placement in ('focus_top_pill', 'post_session_card', 'dashboard_native')
    ),
  ad_unit_id text not null,
  ad_network text not null default 'admob'
    constraint valid_ad_network check (ad_network in ('admob', 'house_promo')),
  focus_session_id uuid references focus_sessions(id) on delete set null,
  clicked boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index idx_ad_impressions_user_placement on ad_impressions (user_id, placement, created_at desc);

create trigger trg_ad_impressions_updated_at
before update on ad_impressions
for each row execute function set_updated_at();

-- =============================================================================
-- 7. weekly_rank_entries
-- Stores weekly focused time per user for Global and Friends leaderboards (S15).
-- =============================================================================
create table weekly_rank_entries (
  id uuid primary key default gen_random_uuid(),
  week_start_date date not null,
  user_id uuid not null references wallet_profiles(user_id) on delete cascade,
  username text not null,
  card_skin_id text not null default 'metal-classic',
  card_label text not null default 'LOCK IN CARD',
  focused_seconds integer not null default 0
    constraint non_negative_focused_seconds check (focused_seconds >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint unique_user_week unique (week_start_date, user_id)
);

create index idx_weekly_rank_leaderboard on weekly_rank_entries (week_start_date, focused_seconds desc);
create index idx_weekly_rank_user on weekly_rank_entries (user_id, week_start_date desc);

create trigger trg_weekly_rank_entries_updated_at
before update on weekly_rank_entries
for each row execute function set_updated_at();

-- =============================================================================
-- 8. friendships
-- Bidirectional friend links for the Friends leaderboard tab on S15.
-- =============================================================================
create table friendships (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references wallet_profiles(user_id) on delete cascade,
  friend_user_id uuid not null references wallet_profiles(user_id) on delete cascade,
  status text not null default 'accepted'
    constraint valid_friendship_status check (status in ('pending', 'accepted')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint no_self_friend check (user_id <> friend_user_id),
  constraint unique_friendship_pair unique (user_id, friend_user_id)
);

create index idx_friendships_user on friendships (user_id, status);
create index idx_friendships_friend on friendships (friend_user_id, status);

create trigger trg_friendships_updated_at
before update on friendships
for each row execute function set_updated_at();

-- =============================================================================
-- Row Level Security (RLS) Policies
-- =============================================================================
alter table wallet_profiles enable row level security;
alter table block_rules enable row level security;
alter table focus_sessions enable row level security;
alter table unlock_sessions enable row level security;
alter table ledger_transactions enable row level security;
alter table ad_impressions enable row level security;
alter table weekly_rank_entries enable row level security;
alter table friendships enable row level security;

-- wallet_profiles: users can read/update only their own profile
create policy wallet_profiles_owner_all on wallet_profiles
  for all using (auth.uid() = user_id) with check (auth.uid() = user_id);

-- block_rules: strictly private to the device/user owner
create policy block_rules_owner_all on block_rules
  for all using (auth.uid() = user_id) with check (auth.uid() = user_id);

-- focus_sessions: strictly private to the owner
create policy focus_sessions_owner_all on focus_sessions
  for all using (auth.uid() = user_id) with check (auth.uid() = user_id);

-- unlock_sessions: strictly private to the owner
create policy unlock_sessions_owner_all on unlock_sessions
  for all using (auth.uid() = user_id) with check (auth.uid() = user_id);

-- ledger_transactions: owner can read and insert via atomic RPC
create policy ledger_transactions_owner_select on ledger_transactions
  for select using (auth.uid() = user_id);
create policy ledger_transactions_owner_insert on ledger_transactions
  for insert with check (auth.uid() = user_id);

-- ad_impressions: owner can insert/read own impressions
create policy ad_impressions_owner_all on ad_impressions
  for all using (auth.uid() = user_id) with check (auth.uid() = user_id);

-- weekly_rank_entries: authenticated users can read the weekly leaderboard;
-- users can only insert/update their own row
create policy weekly_rank_public_read on weekly_rank_entries
  for select using (true);
create policy weekly_rank_owner_write on weekly_rank_entries
  for all using (auth.uid() = user_id) with check (auth.uid() = user_id);

-- friendships: visible to either side of the friendship; creatable by user_id
create policy friendships_participant_select on friendships
  for select using (auth.uid() = user_id or auth.uid() = friend_user_id);
create policy friendships_owner_write on friendships
  for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
